import json
import datetime

MENU = [
    {"id": "1", "name": "蛋餅", "price": 30},
    {"id": "2", "name": "燒餅油條", "price": 45},
    {"id": "3", "name": "培根蛋吐司", "price": 40},
    {"id": "4", "name": "火腿蛋三明治", "price": 45},
    {"id": "5", "name": "鐵板麵", "price": 55},
    {"id": "6", "name": "蘿蔔糕", "price": 35},
    {"id": "7", "name": "豆漿", "price": 25},
    {"id": "8", "name": "奶茶", "price": 30},
]

MENU_BY_ID = {m["id"]: m for m in MENU}
VALID_STATUS = ("pending", "preparing", "done")
VALID_DINE = ("dine_in", "takeout")
MAX_QTY = 99

ORDERS = []
_next_id = [1]


def _copy_order(o):
    return {
        "id": o["id"],
        "items": [dict(i) for i in o["items"]],
        "dine_type": o["dine_type"],
        "table_no": o["table_no"],
        "status": o["status"],
        "total": o["total"],
        "created_at": o["created_at"],
    }


def _parse_body(body):
    if not body:
        return None
    try:
        data = json.loads(body.decode("utf-8"))
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    return data


def _menu():
    return 200, {"items": [dict(m) for m in MENU]}


def _create_order(body):
    data = _parse_body(body)
    if data is None:
        return 400, {"error": "請求內容必須是有效的 JSON 物件"}

    raw_items = data.get("items")
    if not isinstance(raw_items, list) or len(raw_items) == 0:
        return 400, {"error": "訂單至少要有一項餐點"}

    dine_type = data.get("dine_type")
    if dine_type not in VALID_DINE:
        return 400, {"error": "用餐方式必須是內用或外帶"}

    table_no = data.get("table_no", "")
    if table_no is None:
        table_no = ""
    if not isinstance(table_no, (str, int)) or isinstance(table_no, bool):
        return 400, {"error": "桌號格式不正確"}
    table_no = str(table_no).strip()
    if dine_type == "dine_in" and table_no == "":
        return 400, {"error": "內用必須填寫桌號"}
    if len(table_no) > 20:
        return 400, {"error": "桌號太長"}

    merged = {}
    order_of_ids = []
    for entry in raw_items:
        if not isinstance(entry, dict):
            return 400, {"error": "餐點項目格式不正確"}
        mid = entry.get("menu_item_id")
        if isinstance(mid, bool) or not isinstance(mid, (str, int)):
            return 400, {"error": "缺少餐點編號"}
        mid = str(mid)
        if mid not in MENU_BY_ID:
            return 400, {"error": "找不到餐點：" + mid}
        qty = entry.get("quantity")
        if isinstance(qty, bool) or not isinstance(qty, int):
            return 400, {"error": "數量必須是整數"}
        if qty < 1:
            return 400, {"error": "數量必須大於 0"}
        if mid not in merged:
            merged[mid] = 0
            order_of_ids.append(mid)
        merged[mid] += qty
        if merged[mid] > MAX_QTY:
            return 400, {"error": "單一餐點數量不可超過 %d" % MAX_QTY}

    items = []
    total = 0
    for mid in order_of_ids:
        m = MENU_BY_ID[mid]
        q = merged[mid]
        items.append({
            "menu_item_id": mid,
            "name": m["name"],
            "price": m["price"],
            "quantity": q,
        })
        total += m["price"] * q

    order = {
        "id": str(_next_id[0]),
        "items": items,
        "dine_type": dine_type,
        "table_no": table_no if dine_type == "dine_in" else table_no,
        "status": "pending",
        "total": total,
        "created_at": datetime.datetime.now().replace(microsecond=0).isoformat(),
    }
    _next_id[0] += 1
    ORDERS.append(order)
    return 201, _copy_order(order)


def _list_orders():
    ordered = sorted(ORDERS, key=lambda o: (o["created_at"], int(o["id"])))
    return 200, {"items": [_copy_order(o) for o in ordered]}


def _update_status(body):
    data = _parse_body(body)
    if data is None:
        return 400, {"error": "請求內容必須是有效的 JSON 物件"}
    oid = data.get("order_id")
    if isinstance(oid, bool) or not isinstance(oid, (str, int)):
        return 400, {"error": "缺少訂單編號"}
    oid = str(oid)
    status = data.get("status")
    if status not in VALID_STATUS:
        return 400, {"error": "狀態必須是 pending、preparing 或 done"}
    for o in ORDERS:
        if o["id"] == oid:
            o["status"] = status
            return 200, _copy_order(o)
    return 404, {"error": "找不到這張訂單"}


def _revenue_today():
    today = datetime.date.today().isoformat()
    count = 0
    amount = 0
    qty_by_item = {}
    for o in ORDERS:
        if not o["created_at"].startswith(today):
            continue
        count += 1
        amount += o["total"]
        for i in o["items"]:
            qty_by_item[i["menu_item_id"]] = qty_by_item.get(i["menu_item_id"], 0) + i["quantity"]
    ranked = sorted(qty_by_item.items(), key=lambda kv: (-kv[1], int(kv[0])))[:3]
    top = [
        {"menu_item_id": mid, "name": MENU_BY_ID[mid]["name"], "quantity": q}
        for mid, q in ranked
    ]
    return 200, {"order_count": count, "total_amount": amount, "top_items": top}


def handle(method, path, body):
    method = (method or "").upper()
    path = path or "/"
    if not path.startswith("/"):
        path = "/" + path
    if len(path) > 1:
        path = path.rstrip("/")
        if path == "":
            path = "/"

    routes = {
        "/menu": {"GET": lambda: _menu()},
        "/orders": {
            "GET": lambda: _list_orders(),
            "POST": lambda: _create_order(body),
        },
        "/orders/status": {"PATCH": lambda: _update_status(body)},
        "/revenue/today": {"GET": lambda: _revenue_today()},
    }

    if path not in routes:
        return 404, {"error": "找不到此路徑"}
    fn = routes[path].get(method)
    if fn is None:
        return 405, {"error": "不支援此請求方法"}
    try:
        return fn()
    except Exception:
        return 500, {"error": "伺服器發生錯誤"}

